#include "KS/SRC/stringx.h"

enum entity_flavor_t {
  ENTITY_CAMERA, ENTITY_ENTITY, ENTITY_MARKER, ENTITY_MIC, ENTITY_LIGHT_SOURCE,
  ENTITY_PARTICLE_GENERATOR, ENTITY_PHYSICAL, ENTITY_ITEM, ENTITY_LIGHT,
  ENTITY_MOBILE, ENTITY_CONGLOMERATE, ENTITY_TURRET, ENTITY_BEAM, ENTITY_SCANNER,
  ENTITY_MORPHABLE_ITEM, ENTITY_SKY, ENTITY_MANIP, ENTITY_SWITCH,
  ENTITY_BOX_TRIGGER, ENTITY_POLYTUBE, ENTITY_LENSFLARE, NUM_ENTITY_FLAVORS,
  IGNORE_FLAVOR
};

class entity_id {
public:
  entity_id(const char *);
};

class entity {
  char data[0x7c];
  entity_flavor_t flavor;
public:
  entity_flavor_t get_flavor() const { return flavor; }
};

class entity_manager {
public:
  static entity_manager *inst();
  entity *find_entity(const entity_id &, entity_flavor_t, bool);
};

extern entity_manager *entity_manager_instance;
__asm__(".equ entity_manager_instance,0x003E5A60");
inline entity_manager *entity_manager::inst() { return entity_manager_instance; }

void error(const stringx &);

inline stringx operator+(const char *left, const stringx &right) {
  stringx result;
  int left_length = __builtin_strlen(left);
  result.make_room(left_length + right.length());
  result.append(left, left_length);
  result.append(right);
  return result;
}

inline stringx operator+(const stringx &left, const char *right) {
  stringx result;
  int right_length = __builtin_strlen(right);
  result.make_room(left.length() + right_length);
  result.append(left);
  result.append(right, right_length);
  return result;
}

class slc_item_t {
public:
  unsigned find_instance(const stringx &n) const;
};

unsigned slc_item_t::find_instance(const stringx& n) const
  {
  if ( n == "NULL" )
    return (unsigned)0;
  const entity* r = entity_manager::inst()->find_entity( entity_id(n.c_str()), IGNORE_FLAVOR, true );
  if ( !r )
    error( "item " + n + " not found\n" );
  else if ( r->get_flavor() != ENTITY_ITEM )
    error( "entity " + n + " is not a item\n" );
  return (unsigned)r;
  }
